INSERT INTO cheatsheet VALUES ('android', 'Referencia buscable de Android: Jetpack Compose, estado y ciclo de vida, Material 3, navegación, Room, red, sistema y build.', 'La plataforma entera en un sitio: Compose, estado, Material 3, datos, sistema y build. Busca por API o por lo que quieres hacer.', 'Buscar: ''LazyColumn'', ''Room'', ''WorkManager'', ''insets''…');
INSERT INTO cheatsheet VALUES ('animacion', 'Referencia buscable de la animación web: el pipeline del navegador, transitions y keyframes, easing y muelles, WAAPI, animaciones dirigidas por scroll, view transitions, offset-path, GSAP con todos sus plugins, accesibilidad y diagnóstico.', 'Todo el movimiento en un sitio: el pipeline, transitions, keyframes, WAAPI, scroll, view transitions, GSAP, accesibilidad y depuración. Busca por API o por el efecto que quieres.', 'Buscar: ''linear()'', ''scroll()'', ''ScrollTrigger'', ''Flip''…');
INSERT INTO cheatsheet VALUES ('astro', 'Referencia buscable de Astro 7: componente .astro, directivas, routing, content collections, islands, SSR, endpoints, actions y CLI.', 'El framework entero en un sitio: componentes, directivas, routing, contenido, islands, servidor y CLI. Busca por sintaxis o por lo que quieres hacer.', 'Buscar: ''getStaticPaths'', ''client:visible'', ''action''…');
INSERT INTO cheatsheet VALUES ('build', 'Referencia buscable del build frontend: pnpm, package.json, Vite, bundlers (Rolldown/Oxc), librerías, monorepos, caching y producción.', 'El camino a producción entero en un sitio: pnpm, Vite, el bundler, librerías, monorepos y caching. Busca por comando o por lo que quieres hacer.', 'Buscar: ''filter'', ''exports'', ''manualChunks'', ''remote cache''…');
INSERT INTO cheatsheet VALUES ('c23', 'Referencia buscable de C23, compilación, build, linking, sanitizers, seguridad y tooling de sistemas.', 'El lenguaje, el toolchain y el tooling de sistemas en un solo sitio. Busca por sintaxis, flag o herramienta.', 'Buscar: ''sanitize'', ''malloc'', ''meson'', ''nullptr''…');
INSERT INTO cheatsheet VALUES ('canvas', 'Referencia buscable del gráfico 2D en la web: contexto 2D, rutas, transformaciones, texto, píxeles, composición, OffscreenCanvas, SVG a fondo, filtros, accesibilidad y visualización de datos.', 'Los dos modelos del gráfico 2D en un sitio: el lienzo y sus píxeles, el documento SVG y sus formas, filtros, accesibilidad y visualización. Busca por API o por lo que quieres dibujar.', 'Buscar: ''drawImage'', ''viewBox'', ''evenodd'', ''mask-type''…');
INSERT INTO cheatsheet VALUES ('cloudflare', 'Referencia buscable de la plataforma Cloudflare: Workers, Wrangler, KV, R2, D1, Durable Objects, Queues, Workers AI y Vectorize.', 'La plataforma del edge en un sitio: Workers, Wrangler, almacenamiento e IA. Busca por API o por lo que quieres hacer.', 'Buscar: ''env.DB'', ''wrangler dev'', ''Durable'', ''AI''…');
INSERT INTO cheatsheet VALUES ('css', 'Referencia buscable del CSS de 2026: la cascada y las capas, selectores modernos, nesting y @scope, custom properties, Grid y subgrid, container queries, unidades, OKLCH, anchor positioning, dialog y popover, y rendimiento.', 'El lenguaje entero en un sitio: cascada, selectores, layout, consultas, tipografía, color, posición y rendimiento. Busca por propiedad o por el problema que tienes.', 'Buscar: ''@layer'', '':has'', ''subgrid'', ''oklch'', ''anchor''…');
INSERT INTO cheatsheet VALUES ('devtools', 'Referencia buscable de Chrome DevTools: atajos y menú de comandos, Elements y la cascada, la consola entera, breakpoints, source maps, Network, Performance, Rendering, Memory, Application, auditoría y el protocolo.', 'Las herramientas enteras en un sitio, por síntoma y por panel. Los atajos van siempre en pareja macOS y Windows/Linux, y nada se describe por su ruta de menú: esas caducan.', 'Buscar: ''retenido'', ''logpoint'', ''HAR'', ''capa''…');
INSERT INTO cheatsheet VALUES ('elm', 'Elm y TEA en un sitio: Model, update, view, Cmd y Sub, tipos, decoders y ports.', 'Elm y TEA en un sitio: Model, update, view, Cmd y Sub, tipos, decoders y ports.', 'Buscar: ''update'', ''Cmd'', ''decoder'', ''Maybe''…');
INSERT INTO cheatsheet VALUES ('estado', 'Referencia buscable del estado: signals, observables, máquinas de estado (XState), Redux/RTK, Elm, TCA, MVI/Orbit, TanStack Query y CRDTs.', 'Todo el estado en un sitio: primitivos, máquinas, Redux, las arquitecturas unidireccionales y el estado del servidor. Busca por API o por lo que quieres hacer.', 'Buscar: ''createMachine'', ''createSlice'', ''TCA'', ''useQuery''…');
INSERT INTO cheatsheet VALUES ('flux', 'De Flux a Redux Toolkit y la ola ligera: store, reducers, middleware, selectores, RTK Query, Zustand y Jotai.', 'De Flux a Redux Toolkit y la ola ligera: store, reducers, middleware, selectores, RTK Query, Zustand y Jotai.', 'Buscar: ''createSlice'', ''thunk'', ''selector'', ''zustand''…');
INSERT INTO cheatsheet VALUES ('ios', 'Referencia buscable de desarrollo iOS: SwiftUI, estado, navegación, SwiftData, async, animaciones, capacidades del sistema y distribución.', 'El desarrollo de apps Apple en un sitio: SwiftUI, estado, datos, sistema y distribución. Busca por API o por lo que quieres hacer.', 'Buscar: ''@State'', ''NavigationStack'', ''@Model'', ''task''…');
INSERT INTO cheatsheet VALUES ('kernel', 'Referencia buscable del kernel de Linux: módulos, memoria, concurrencia, drivers, VFS, red, io_uring, depuración y Rust.', 'Las APIs, comandos y herramientas del kernel en un solo sitio. Busca por función o por lo que quieres hacer.', 'Buscar: ''kmalloc'', ''spinlock'', ''io_uring'', ''ftrace''…');
INSERT INTO cheatsheet VALUES ('kotlin', 'Referencia buscable de Kotlin: tipos y nulabilidad, funciones y lambdas, clases y data class, sealed e interfaces, genéricos y varianza, colecciones y secuencias, delegación y extensiones, funciones de scope, corrutinas y Flow, interoperabilidad con Java, multiplataforma y las herramientas del compilador.', 'El lenguaje entero en un sitio: tipos, clases, genéricos, colecciones, corrutinas, Flow, interoperabilidad y herramientas. Busca por palabra clave o por el problema que tienes.', 'Buscar: ''suspend'', ''sealed'', ''reified'', ''StateFlow'', ''expect''…');
INSERT INTO cheatsheet VALUES ('local-first', 'Referencia buscable de arquitectura local-first: almacenamiento del cliente, SQLite sobre OPFS, Workers, teoría y catálogo de CRDT, algoritmos de secuencia, almacenamiento por contenido, motores de sincronización, identidad y cifrado.', 'La arquitectura entera en un sitio: almacenamiento, concurrencia, convergencia, contenido, red, identidad y producción. Busca por concepto o por API.', 'Buscar: ''OPFS'', ''OR-Set'', ''Merkle'', ''UCAN''…');
INSERT INTO cheatsheet VALUES ('lua', 'Referencia buscable de Lua: los ocho tipos y los dos subtipos numéricos, la tabla por dentro, cadenas y el lenguaje de patrones, funciones y varargs, closures y upvalues, _ENV y los entornos, metatablas y metamétodos, objetos con prototipos, iteradores, corrutinas, módulos, errores con pcall, la biblioteca estándar y el recolector.', 'El lenguaje entero en un sitio: valores, tablas, funciones, metatablas, objetos, corrutinas, módulos, errores y memoria. Busca por función o por el mecanismo que quieres entender.', 'Buscar: ''__index'', ''_ENV'', ''pcall'', ''coroutine'', ''gsub''…');
INSERT INTO cheatsheet VALUES ('maquinas', 'FSM, statecharts y XState en un sitio: estados, transiciones, actores, testing y visualización.', 'FSM, statecharts y XState en un sitio: estados, transiciones, actores, testing y visualización.', 'Buscar: ''createMachine'', ''guard'', ''invoke'', ''spawn''…');
INSERT INTO cheatsheet VALUES ('mvi', 'MVI en Kotlin y Android: intents, estado inmutable, side effects, Orbit, coroutines, Flow y Compose.', 'MVI en Kotlin y Android: intents, estado inmutable, side effects, Orbit, coroutines, Flow y Compose.', 'Buscar: ''intent'', ''reduce'', ''StateFlow'', ''container''…');
INSERT INTO cheatsheet VALUES ('neovim', 'Referencia buscable de todos los atajos y comandos de Neovim de la guía.', 'Toda la munición de la guía en un solo sitio. Busca por tecla o por lo que quieres hacer.', 'Buscar: ''borrar palabra'', ''gd'', ''grep'', ''macro''…');
INSERT INTO cheatsheet VALUES ('reactividad-fina', 'Referencia buscable de la reactividad de grano fino: granularidad, el grafo de dependencias, tracking automático, push-pull, glitches, memoización, el árbol de dueños, lotes, proxies, los motores comparados y TC39.', 'La máquina entera en un sitio: el grafo, el tracking, la propagación, la consistencia, la propiedad y la planificación. Son conceptos y mecanismos, no la API de ninguna librería.', 'Buscar: ''rombo'', ''quizá sucio'', ''dueño'', ''proxy''…');
INSERT INTO cheatsheet VALUES ('rendimiento', 'Referencia buscable del rendimiento web: Core Web Vitals y sus umbrales, red y caché, ruta crítica y pistas de recurso, imágenes, coste del JavaScript, hilo principal e INP, CLS y fuentes, render, memoria, service workers y CI.', 'Las tres fases enteras en un sitio: métricas y umbrales, red y caché, el coste del JavaScript, el hilo principal, el pipeline de píxeles, memoria y estrategias de carga. Busca por métrica o por síntoma.', 'Buscar: ''INP'', ''immutable'', ''sizes'', ''contain''…');
INSERT INTO cheatsheet VALUES ('rust', 'Referencia buscable de Rust: ownership, traits, iteradores, errores, concurrencia, async, unsafe, no_std y cargo.', 'El lenguaje entero en un sitio: ownership, traits, async, unsafe y el tooling. Busca por sintaxis o por lo que quieres hacer.', 'Buscar: ''ownership'', ''Arc'', ''async'', ''trait''…');
INSERT INTO cheatsheet VALUES ('solid', 'Referencia buscable de SolidJS: signals, efectos, memos, stores, control flow, resources, context y SolidStart.', 'La reactividad fina entera en un sitio: primitivos, control flow, stores, async y SolidStart. Busca por API o por lo que quieres hacer.', 'Buscar: ''createSignal'', ''For'', ''store'', ''use server''…');
INSERT INTO cheatsheet VALUES ('swift', 'Referencia buscable del lenguaje Swift: tipos y valores, opcionales, genéricos, closures, concurrencia, memoria, macros y SPM.', 'El lenguaje entero en un sitio: tipos, opcionales, genéricos, concurrencia, memoria y metaprogramación. Busca por sintaxis o por lo que quieres hacer.', 'Buscar: ''guard'', ''actor'', ''some'', ''weak''…');
INSERT INTO cheatsheet VALUES ('tca', 'TCA en un sitio: State, Action, Reducer, Effect y Store; composición, dependencias, navegación y testing.', 'TCA en un sitio: State, Action, Reducer, Effect y Store; composición, dependencias, navegación y testing.', 'Buscar: ''@Reducer'', ''Effect'', ''@Dependency'', ''TestStore''…');
INSERT INTO cheatsheet VALUES ('three', 'Referencia buscable de Three.js y 3D en la web: la tríada y el bucle, espacios y matrices, BufferGeometry e instancing, materiales y PBR, texturas, luces y sombras, IBL, glTF, animación, shaders GLSL, TSL con WebGPURenderer, raycasting, rendimiento y dispose.', 'De la matriz al shader en un solo sitio: geometría, materiales, luz, assets, shaders, TSL y producción. Busca por API o por lo que quieres conseguir.', 'Buscar: ''BufferGeometry'', ''PMREM'', ''TSL'', ''dispose''…');
INSERT INTO cheatsheet VALUES ('webgpu', 'Referencia buscable de WebGPU: adaptador y dispositivo, canvas, buffers y comandos, WGSL a fondo, bind groups y alineación, texturas y samplers, render pipeline, depth y mezcla, multisampling, indirect, compute shaders, rendimiento y depuración.', 'La API entera en un solo sitio: dispositivo, buffers, WGSL, recursos, pipeline, compute, medición y depuración. Busca por nombre o por lo que quieres conseguir.', 'Buscar: ''bind group'', ''WGSL'', ''workgroup'', ''mapAsync''…');
