INSERT INTO cheatsheet_item VALUES ('animacion', 0, 0, 'Style · layout · paint · composite', 'Cuatro etapas; tocar una arrastra a todas las de abajo');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 1, '16,7 ms a 60 Hz', 'El fotograma entero; tuyos son unos 10 ms, no los dieciséis');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 2, 'width, top, margin', 'Disparan layout: la etapa que recorre el árbol entero');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 3, 'background-color, box-shadow', 'Se saltan layout, pero repintan la capa');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 4, 'transform · opacity', 'Solo composición: el trabajo se lo queda la GPU');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 5, 'filter', 'Compositable, pero cada función tiene su precio');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 6, 'Capa de composición', 'Una textura aparte en memoria: no salen gratis');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 7, 'Fuera del hilo principal', 'La animación sigue aunque el JavaScript se atasque');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 8, 'will-change', 'Pista, no arreglo: dejarlo puesto siempre es peor que nada');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 9, 'Descalificación silenciosa', 'Sin error ni aviso: solo va a tirones en gama media');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 10, 'La que viene del ancestro', 'Un filter o un blend arriba aplana todo tu subárbol');
INSERT INTO cheatsheet_item VALUES ('animacion', 0, 11, 'Layer borders · Paint flashing', 'Los overlays que enseñan qué se promovió y qué repinta');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 0, 'El disparador', 'Un cambio de estilo: sin dos valores no hay transición');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 1, 'transition-property', 'Enumera; all acaba animando cosas que no querías');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 2, 'transition-duration', 'Su valor inicial es 0s: sin ella no ocurre nada');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 3, 'transition-delay', 'En negativo arranca la transición ya empezada');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 4, 'transition-timing-function', 'La curva; el valor por defecto es ease, no linear');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 5, 'Valores interpolables', 'Los que el motor sabe convertir en una lista de números');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 6, 'Propiedades discretas', 'Saltan al 50% del recorrido salvo que las habilites');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 7, 'La que no dispara', 'El elemento aún no existía, o el valor de partida era auto');
INSERT INTO cheatsheet_item VALUES ('animacion', 1, 8, 'La abreviatura reinicia', 'Escribir transition después borra el transition-behavior');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 0, 'cubic-bezier(x1, y1, x2, y2)', 'Dos puntos de control; los extremos están clavados');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 1, 'Y fuera del rango 0 a 1', 'Permitido: así se hacen la anticipación y el rebote');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 2, 'ease', 'El defecto: arranca rápido y frena; no es simétrico');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 3, 'La pendiente es velocidad', 'Un tramo plano en la curva es una pausa en pantalla');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 4, 'steps(5, jump-end)', 'Saltos discretos para sprites y contadores');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 5, 'jump-start · end · none · both', 'Los cuatro modos de reparto de los saltos');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 6, 'linear(0, 0.25 30%, 1)', 'Curva arbitraria por puntos: la puerta al muelle en CSS');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 7, 'Entrada frente a salida', 'Lo que se va, rápido; lo que llega, con freno');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 8, 'Oscilador amortiguado', 'Fuerza proporcional al desplazamiento más rozamiento');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 9, 'Rigidez · masa · amortiguación', 'Tres parámetros que un diseñador sí sabe ajustar');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 10, 'Ratio de amortiguación', 'El número que decide si rebota o si solo frena');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 11, 'Subamortiguado', 'Rebota: para lo que quiere sentirse vivo');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 12, 'Críticamente amortiguado', 'Llega en el mínimo tiempo sin pasarse ni una vez');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 13, 'Sobreamortiguado', 'Se arrastra hasta el reposo: casi nunca es lo que buscas');
INSERT INTO cheatsheet_item VALUES ('animacion', 2, 14, 'Un muelle no tiene duración', 'Tiene condición de parada; por eso hay que muestrearlo');
INSERT INTO cheatsheet_item VALUES ('animacion', 3, 0, '@starting-style', 'El estado desde el que parte algo que acaba de existir');
INSERT INTO cheatsheet_item VALUES ('animacion', 3, 1, 'Sin él no hay dos valores', 'Y sin dos valores el navegador no transiciona nada');
INSERT INTO cheatsheet_item VALUES ('animacion', 3, 2, 'transition-behavior: allow-discrete', 'Deja que las discretas esperen al final del recorrido');
INSERT INTO cheatsheet_item VALUES ('animacion', 3, 3, 'display: none', 'Con allow-discrete el salto ocurre cuando acaba, no antes');
INSERT INTO cheatsheet_item VALUES ('animacion', 3, 4, 'overlay', 'Mantiene el elemento en la capa superior mientras se va');
INSERT INTO cheatsheet_item VALUES ('animacion', 3, 5, 'El orden de las declaraciones', 'La abreviatura transition borra el behavior que pusiste antes');
INSERT INTO cheatsheet_item VALUES ('animacion', 3, 6, 'height: auto', 'Nunca fue interpolable: auto no es una longitud');
