INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 0, 'val', 'Congela la referencia, nunca el objeto al que apunta');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 1, 'Inferencia local', 'Deduce dentro del cuerpo; la firma pública se anota a mano');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 2, 'if y when devuelven valor', 'Por eso Kotlin no necesita un operador ternario');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 3, 'when sin sujeto', 'Cadena de condiciones cuando no hay un valor que comparar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 4, 'Unit', 'Un tipo con un único valor, no el vacío de C');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 5, 'Nothing', 'El tipo del fondo: no tiene valores, marca la rama que no vuelve');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 6, 'throw y return son expresiones', 'Su tipo es Nothing, y por eso encajan tras un elvis');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 7, 'Sin conversión numérica implícita', 'Un Int no se cuela en un Long: la conversión se escribe');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 8, 'Rangos y progresiones', 'downTo y step producen lo que el for recorre de verdad');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 9, 'Plantillas de cadena', 'El dólar interpola; las triples comillas no escapan nada');
INSERT INTO cheatsheet_item VALUES ('kotlin', 0, 10, 'Etiquetas en bucles', 'break y continue eligen a qué bucle apuntan');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 0, 'T frente a T?', 'Dos tipos distintos, con T como subtipo del nulable');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 1, '?.', 'Corta la cadena y devuelve null en lugar de lanzar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 2, '?:', 'Elvis: la función total que da salida a la rama nula');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 3, 'Nothing tras el elvis', 'Permite cerrar con throw o return sin romper el tipo');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 4, '!!', 'Aserción: pides tú el NPE, y sale con tu número de línea');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 5, 'Smart cast', 'El compilador demuestra la no nulidad y te ahorra el cast');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 6, 'Estabilidad', 'Un var de otro módulo o una propiedad open rompen la demostración');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 7, 'Platform type', 'El tercer estado que llega de Java y no se puede escribir');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 8, 'Anotaciones de nulabilidad', 'JSpecify en la fuente Java devuelve la garantía al tipo');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 9, 'Nothing?', 'El tipo cuyo único valor posible es null');
INSERT INTO cheatsheet_item VALUES ('kotlin', 1, 10, 'Diseñar sin nulls', 'Cuatro campos opcionales son dieciséis estados representables');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 0, 'Cuerpo de expresión', 'Con el igual se infiere el retorno; con llaves hay que declararlo');
