INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 2, 'Argumentos con nombre', 'Se evalúan en el orden en que tú los escribes, no en el de la firma');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 3, 'vararg y el asterisco', 'Un array desplegado dentro de la llamada, no pasado como uno');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 4, 'infix', 'Un receptor, un parámetro y ningún punto ni paréntesis');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 5, 'Funciones locales', 'Reutilizan el ámbito sin ampliar la superficie pública');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 6, 'Nivel superior', 'El compilador fabrica una clase FicheroKt donde alojarlas');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 7, 'Tipos función', '(A) -> B es un tipo, y su aridad forma parte de él');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 8, 'it', 'Solo con un parámetro; en cuanto hay dos, ponles nombre');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 9, 'Lambda final fuera', 'El paréntesis se queda vacío y la llamada parece sintaxis');
INSERT INTO cheatsheet_item VALUES ('kotlin', 2, 10, '::referencia', 'En lugar de una lambda que se limita a llamar a algo que ya existe');
