INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 5, 'override vuelve a abrir', 'Sigue siendo sobrescribible salvo que lo cierres con final');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 6, 'internal', 'Visible en el módulo; sale public al bytecode con el nombre decorado');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 7, 'nested frente a inner', 'Sin inner no hay referencia a la instancia externa');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 8, 'object', 'Singleton del lenguaje, con la instancia creada de forma segura');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 9, 'companion object', 'La ausencia de static, con un objeto real y una indirección detrás');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 10, 'const val', 'El valor se copia en cada uso: cambiarlo obliga a recompilar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 11, 'Expresión de objeto', 'Instancia nueva en cada evaluación, y captura su entorno');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 12, 'invoke en el compañero', 'Una llamada que se lee como una construcción');
INSERT INTO cheatsheet_item VALUES ('kotlin', 3, 13, 'Estado en un object', 'Retención permanente y pruebas que se contaminan entre sí');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 0, 'data', 'Genera equals, hashCode, toString, copy y las componentN');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 1, 'Solo el constructor primario', 'Lo declarado en el cuerpo queda fuera de equals y de copy');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 2, 'copy', 'Copia superficial: lo anidado se sigue compartiendo');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 3, 'Actualizar sin mutar', 'copy con argumentos con nombre; con estructuras anidadas, un muro');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 4, '==', 'Llama a equals con la comprobación de nulos ya incorporada');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 5, '===', 'La identidad, que es justo lo que == no compara');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 6, 'componentN', 'Reordenar el constructor rompe a tus usuarios en silencio');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 7, 'Desestructurado por nombre', 'Llegó en 2.3.20 y quita el peligro de la posición');
INSERT INTO cheatsheet_item VALUES ('kotlin', 4, 8, 'Cuándo no usar data', 'Entidades con identidad, jerarquías y APIs que no pueden dar copy');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 0, 'sealed class', 'Jerarquía cerrada: el compilador conoce todos los casos posibles');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 1, 'sealed interface', 'Cierra el conjunto sin gastar el único hueco de herencia');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 2, 'Dónde viven las subclases', 'El módulo y el paquete delimitan quién puede entrar en la jerarquía');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 3, 'when exhaustivo', 'Sobre un tipo cerrado hay que cubrirlo todo, también en sentencia');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 4, 'Resolución sensible al contexto', 'Desde 2.3 el caso se escribe sin cualificarlo entero');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 5, 'Tipo suma', 'Cuenta los estados: cuatro banderas booleanas son dieciséis');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 6, 'entries', 'Sustituye a values() y no asigna un array nuevo en cada llamada');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 7, 'El límite del enum', 'Cuando cada entrada quiere sus propios datos, toca sealed');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 8, 'fun interface', 'Un solo método abstracto habilita pasar una lambda en su lugar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 9, 'Interfaz con cuerpo', 'Puede llevar código; no puede llevar un solo byte de estado');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 10, 'Propiedades en interfaces', 'Declaran la forma y dejan el almacén a quien implemente');
INSERT INTO cheatsheet_item VALUES ('kotlin', 5, 11, 'Sellar o abrir', 'El problema de la expresión: eliges qué eje de extensión regalas');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 0, 'by en los supertipos', 'El compilador escribe los reenvíos: decorador sin una línea por método');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 1, 'El envío que no vuelve', 'Lo que llama el delegado no pasa por tus sobrescrituras');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 2, 'by lazy', 'Tres modos de sincronización, y la excepción no se cachea');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 3, 'observable', 'Notifica el cambio después de haberlo aplicado');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 4, 'vetoable', 'Devuelve false y la asignación no llega a ocurrir');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 5, 'Delegar en un Map', 'Cada propiedad lee su clave del mapa que le pases');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 6, 'getValue y setValue', 'Es una convención por nombre: no hace falta implementar interfaz');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 7, 'provideDelegate', 'El gancho que corre al crear el delegado, con la KProperty en la mano');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 8, 'lateinit', 'Promete inicializar antes de leer, y la excepción dice cuál falló');
