INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 10, 'Una extensión es estática', 'Función suelta que recibe el receptor como primer parámetro');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 11, 'Resolución estática', 'Manda el tipo escrito, no el objeto que hay dentro');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 12, 'El miembro siempre gana', 'Una extensión nunca sobrescribe lo que la clase ya tiene');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 13, 'Propiedad de extensión', 'Un accesor con otro nombre: no hay campo detrás que llenar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 6, 14, 'Receptor nulable', 'La extensión puede recibir null y decidir ella qué hacer');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 0, 'Los dos ejes', 'Receptor o argumento; devolver el objeto o el resultado de la lambda');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 1, 'let', 'El objeto llega como it y sale lo que calcules: transformar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 2, 'also', 'El objeto como it y devuelve el objeto: para efectos al margen');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 3, 'run', 'El objeto como this y devuelve el resultado del bloque');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 4, 'with', 'Lo mismo que run, pero el objeto va como argumento y no como receptor');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 5, 'apply', 'El objeto como this y lo devuelve: configurar antes de entregar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 6, 'takeIf', 'El valor si cumple, null si no: engancha con un elvis');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 7, 'takeUnless', 'El mismo filtro con la condición al revés, para leerlo mejor');
INSERT INTO cheatsheet_item VALUES ('kotlin', 7, 8, 'El criterio', 'No es un problema técnico sino editorial: ¿se lee mejor así?');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 0, 'Por qué existe inline', 'Mata la instancia de la lambda, la llamada virtual y el boxing');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 1, 'noinline', 'Para el parámetro que sí necesitas guardar en algún sitio');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 2, 'crossinline', 'Prohíbe el retorno no local dentro de esa lambda');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 3, 'Cuándo no insertar', 'El coste crece con el cuerpo y con el número de puntos de llamada');
