INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 5, 'Solo dentro de inline', 'Sin inserción no hay sitio donde escribir el tipo concreto');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 6, 'Restricciones', 'Un límite superior en la declaración, y el resto en la cláusula where');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 7, 'out', 'Solo produce: una lista de perros pasa donde piden animales');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 8, 'in', 'Solo consume, y la relación de subtipo va en sentido contrario');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 9, 'Proyección de uso', 'Pedir la flexibilidad firma a firma cuando la clase hace las dos cosas');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 10, 'Proyección estrella', 'No sé el argumento de tipo y declaro que no lo voy a necesitar');
INSERT INTO cheatsheet_item VALUES ('kotlin', 8, 11, 'Borrado de tipos', 'Desaparece el argumento, no el nombre de la clase que lo lleva');
