INSERT INTO cheatsheet_item VALUES ('lua', 0, 0, 'Ocho tipos', 'nil, boolean, number, string, function, table, userdata y thread');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 1, 'type y math.type', 'El segundo revela el subtipo numérico que el primero oculta');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 2, 'Las variables no tienen tipo', 'El valor lo lleva encima; la variable solo lo sostiene');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 3, 'Solo nil y false son falsos', 'El cero y la cadena vacía son verdaderos, sin excepción');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 4, 'and y or', 'Devuelven uno de sus operandos, no un booleano');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 5, 'nil', 'Un valor de pleno derecho: asignarlo borra la clave por completo');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 6, 'Cuatro se copian, cuatro se comparten', 'Ahí está la frontera entre valor e identidad');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 7, 'El cisma de 5.3', 'Un solo tipo number partido en dos subtipos: entero y flotante');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 8, '/ frente a //', 'La barra siempre da flotante; la doble redondea hacia abajo');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 9, '%', 'El módulo hereda el signo del divisor, no el del dividendo');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 10, '^', 'La potencia nunca devuelve un entero');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 11, 'Desbordamiento', '64 bits en complemento a dos: da la vuelta sin fallar');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 12, 'math.tointeger', 'Convierte solo si la conversión es exacta; math.floor convierte siempre');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 13, 'NaN', 'No es igual ni a sí mismo, y por eso no puede ser clave');
INSERT INTO cheatsheet_item VALUES ('lua', 0, 14, 'Coerción', 'Funciona en la aritmética y falla como clave de tabla');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 0, 'Una sola estructura', 'Array, diccionario, objeto, módulo, conjunto y espacio de nombres');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 1, 'Representación dual', 'Un vector para los enteros densos y una hash encadenada para el resto');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 2, 'Claves prohibidas', 'Solo nil y NaN; hasta una tabla o una función sirven de clave');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 3, '2.0 y 2', 'El flotante con parte decimal nula se normaliza antes de buscar');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 4, 'El constructor', 'Lista posicional, clave con nombre y clave entre corchetes, mezclables');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 5, 'La última expresión', 'Se expande a todos sus valores; en medio, se recorta a uno');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 6, 'El operador de longitud', 'Devuelve una frontera, no un recuento, y le cuesta O(log n)');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 7, 'Agujero', 'Con un hueco la tabla deja de ser secuencia y la longitud miente');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 8, 'El rehash', 'No crece un poco: recuenta y redimensiona las dos partes de golpe');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 9, 'Borrar no libera', 'La memoria vuelve en el próximo redimensionado, no al asignar nil');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 10, 'Arrays compactos de 5.5', 'Sin el relleno de alineación, una tabla grande baja al sesenta por ciento');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 11, 'La tabla como conjunto', 'El elemento de clave y true de valor: pertenencia en tiempo constante');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 12, 'La cola con dos índices', 'Primero y último avanzan y no se desplaza ni un elemento');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 13, 'Registro de funciones', 'Una tabla de despacho en lugar de la escalera de condicionales');
INSERT INTO cheatsheet_item VALUES ('lua', 1, 14, 'table.move', 'Copia rangos, también sobre la misma tabla, y respeta el solapamiento');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 0, 'Valor inmutable', 'Cada concatenación fabrica una cadena nueva y entera');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 1, 'Concatenar en un bucle', 'Coste cuadrático; el patrón correcto acumula y hace table.concat');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 2, 'Internamiento', 'Las cortas comparten una copia: igualdad en tiempo constante');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 3, 'Las largas no se internan', 'El precio que se paga por no cargar la tabla global de cadenas');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 4, 'Índices negativos', 'Cuentan desde el final, y el menos uno es el último byte');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 5, '[[ ]]', 'Cadena larga con niveles: ni escapes ni comillas que estorben');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 6, 'string.format', 'El motor de formateo; con %q el valor sale como Lua releíble');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 7, 'utf8', 'Lua trabaja con bytes: la biblioteca solo ayuda a recorrerlos');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 8, 'No son expresiones regulares', 'Otro formalismo, nacido de una restricción de tamaño y portabilidad');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 9, '%a %d %s %w', 'Diez clases con su complemento en mayúscula; %w no incluye el guion bajo');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 10, 'El punto', 'Cualquier byte, salto de línea incluido: no hay modo multilínea');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 11, '* + - ?', 'Tres cuantificadores codiciosos y un único perezoso, el guion');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 12, 'El cuantificador', 'Afecta solo a la clase anterior, porque no existen los grupos');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 13, '%1', 'Referirse dentro del patrón a una captura que ya se hizo');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 14, 'Captura de posición', 'Un paréntesis vacío devuelve el índice, no el texto');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 15, '%b y %f', 'Coincidencia equilibrada y frontera: lo que no cabía en el formalismo');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 16, 'find, match, gmatch, gsub', 'Localizar, extraer, iterar y sustituir: las cuatro y ninguna más');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 17, 'gsub con tabla o función', 'El reemplazo se puede consultar o calcular, no solo escribir');
INSERT INTO cheatsheet_item VALUES ('lua', 2, 18, 'Sin alternancia', 'Cuando la echas de menos, el sitio al que ir es LPeg');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 0, 'Declarar es asignar', 'No hay categoría sintáctica: se crea un valor y se guarda en algún sitio');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 1, 'local function', 'Declara primero y asigna después; sin eso no habría recursión directa');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 2, 'Siempre por valor', 'De una tabla se copia la referencia, nunca la estructura apuntada');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 3, 'Ajuste de aridad', 'Los que faltan llegan nil y los que sobran se tiran, en silencio');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 4, 'f{...} y f''...''', 'Con un único argumento literal el paréntesis se puede omitir');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 5, 'Los dos puntos', 'Azúcar que inserta el receptor como primer argumento, y nada más');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 6, 'Retornos múltiples', 'Una llamada no produce un valor sino una lista de longitud arbitraria');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 7, 'La regla de ajuste', 'Al final de una lista se expande; en cualquier otro sitio se recorta a uno');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 8, '(f())', 'El único contexto donde los paréntesis dejan de ser inertes: truncan');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 9, '...', 'Los argumentos variables, sujetos exactamente a la misma regla de ajuste');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 10, 'select con almohadilla', 'Contar cuántos llegaron de verdad, incluidos los nil de en medio');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 11, 'table.pack', 'Materializa con un campo n, porque la longitud no vale con agujeros');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 12, 'Tablas de varargs con nombre', 'Novedad de 5.5: declarar la tabla directamente en los parámetros');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 13, 'Llamada de cola', 'No es una optimización sino una definición del manual: no consume pila');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 14, 'Qué la descalifica', 'Un paréntesis, una suma pendiente o una variable de cierre por delante');
INSERT INTO cheatsheet_item VALUES ('lua', 3, 15, 'Máquinas de estados', 'Cada estado retorna al siguiente y corren para siempre en espacio constante');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 0, 'Toda función es un closure', 'Un prototipo compilado más el vector de variables externas que captura');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 1, 'Upvalue abierto', 'Apunta a un hueco vivo de la pila mientras el bloque siga existiendo');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 2, 'Upvalue cerrado', 'Al salir del bloque el valor migra al montón y el puntero se reengancha');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 3, 'Compartir estado', 'Dos closures del mismo ámbito ven exactamente la misma celda');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 4, 'El objeto sin tabla', 'Estado verdaderamente privado, pagado en una función por campo');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 5, 'La trampa del bucle', 'Lua no la sufre: cada iteración abre y cierra su propio bloque');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 6, 'local', 'La variable empieza a existir después de su propia declaración');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 7, '200 locales', 'El límite por función que impone el compilador');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 8, '<const>', 'No asignable, comprobado al compilar, y a veces ni llega a ocupar registro');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 9, '<close>', 'El RAII de Lua: __close al salir del bloque, también por error o break');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 10, '_ENV', 'Un upvalue corriente: toda global es un campo suyo');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 11, '_G', 'No tiene nada de especial: es el valor inicial de _ENV');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 12, 'El coste de un global', 'Leer un nombre libre es un acceso a tabla, no una lectura de registro');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 13, 'Cachear en local', 'El idioma de bajar la función de biblioteca al ámbito de la función');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 14, 'global de 5.5', 'Declararlas convierte el error tipográfico en error de compilación');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 15, 'Sandbox', 'La frontera real no es el nombre visible sino el objeto alcanzable');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 16, 'debug.getupvalue', 'Enumerar y modificar capturas desde fuera del closure');
INSERT INTO cheatsheet_item VALUES ('lua', 4, 17, 'upvalueid y upvaluejoin', 'Comprobar si dos funciones comparten celda, y redirigir una captura');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 0, 'La idea', 'Una tabla que describe a otra: Lua expone el punto de decisión');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 1, 'setmetatable y getmetatable', 'Instalar y leer, salvo que __metatable lo impida');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 2, '__index con tabla', 'Delegación: la búsqueda fallida sigue por el eslabón siguiente');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 3, '__index con función', 'Cálculo: la clave ausente se fabrica en el momento de pedirla');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 4, '__newindex', 'Solo se dispara con claves ausentes; reasignar no lo despierta');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 5, 'El proxy vacío', 'Tabla sin claves y almacén aparte, para que todo pase por los metamétodos');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 6, 'rawget y rawset', 'Puertas traseras obligatorias cuando el metamétodo toca su propia tabla');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 7, 'rawlen y rawequal', 'Longitud e igualdad sin pasar por __len ni por __eq');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 8, 'Memoización', '__index calcula una vez y guarda; con tabla débil, sin filtrar memoria');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 9, 'Aritméticos y __concat', 'Gana el metamétodo del primer operando que lo tenga; no hay reflejados');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 10, '__call', 'Una tabla que se invoca como si fuera una función');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 11, '__tostring y __name', 'Cómo se imprime tu tipo y cómo aparece en los mensajes de error');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 12, '__len', 'Definir la propia longitud aunque la tabla tenga agujeros');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 13, '__eq', 'Solo entre valores del mismo tipo, y solo si la identidad ya falló');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 14, '__lt y __le', 'Se llaman con cualquier par; en 5.4 __le perdió su respaldo');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 15, '__gc', 'Solo si estaba puesto al asignar la metatabla, y puede no correr nunca');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 16, '__close', 'Cierre garantizado a la salida del bloque, sea cual sea esa salida');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 17, '__mode', 'Convierte la tabla en observadora: claves o valores débiles');
INSERT INTO cheatsheet_item VALUES ('lua', 5, 18, '__metatable', 'Oculta y protege: ni se lee la metatabla ni se sustituye');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 0, 'No hay clases', 'Solo tablas, metatablas y una convención de llamada');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 1, 'El idioma de la clase', 'Una tabla que es clase y metatabla a la vez, con __index a sí misma');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 2, 'El constructor', 'Crear la tabla vacía y ponerle la clase como metatabla');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 3, 'self', 'En la declaración con dos puntos aparece solo; en la llamada, el receptor');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 4, 'El error clásico', 'Mezclar el punto y los dos puntos, y quedarse sin receptor');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 5, 'Herencia', 'Encadenar metatablas: la búsqueda sube un eslabón cada vez que falla');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 6, 'Llamar al padre', 'Invocar su método pasándole el self del hijo a mano');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 7, 'Herencia múltiple', '__index como función que recorre varias tablas en orden');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 8, 'El coste de la cadena', 'Cada eslabón es otra búsqueda fallida antes de acertar');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 9, 'Encapsulación real', 'Campos como closures; el guion bajo es convención, no protección');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 10, 'La tabla privada', 'Vía intermedia: el estado aparte, con claves débiles para no retener');
INSERT INTO cheatsheet_item VALUES ('lua', 6, 11, 'Cuándo no', 'Composición explícita, o directamente ningún objeto');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 0, 'La tripleta', 'Función iteradora, estado invariante y variable de control');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 1, 'El cuarto valor', 'Un valor de cierre que se cierra al abandonar el bucle');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 2, 'Se evalúa una sola vez', 'La lista de expresiones; después el bucle solo llama a la función');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 3, 'El nil de parada', 'El primer resultado nulo termina el bucle, sin más condición');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 4, 'pairs', 'No recorre nada: devuelve next, la tabla y nil');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 5, 'ipairs', 'Fabrica un contador desde 1 y se rinde en el primer hueco');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 6, 'El orden de pairs', 'Indefinido por construcción: depende de cómo se construyó la tabla');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 7, 'Iterador sin estado', 'Función pura de estado y control: el más barato del lenguaje');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 8, 'Iterador con estado', 'Un closure por bucle; ni reentrante ni reiniciable');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 9, '__pairs', 'Hace mentir a pairs, y por eso conviene pensárselo dos veces');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 10, 'Iterador con corrutina', 'Escribe solo el recorrido recursivo, y trae su propio coste');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 11, 'Componer iteradores', 'Filtros y transformaciones perezosas sin tablas intermedias');
INSERT INTO cheatsheet_item VALUES ('lua', 7, 12, 'Control inmutable en 5.5', 'Las variables del for dejan de poder asignarse dentro del cuerpo');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 0, 'Qué es', 'Una línea de ejecución con pila propia que cede donde tú lo escribiste');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 1, 'Asimétrica', 'Devuelve el control a quien la reanudó, no a un planificador');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 2, 'No preemptiva', 'Nadie la interrumpe: sin carreras, y también sin paralelismo');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 3, 'El coste', 'Alrededor de un kilobyte, y el cambio vale lo que una llamada');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 4, 'create', 'Fabrica la corrutina y no ejecuta ni una sola línea');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 5, 'resume y yield', 'Reanudar arranca o continúa; ceder devuelve a la suspensión');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 6, 'Cuatro canales', 'El primer resume alimenta los parámetros; los siguientes salen por yield');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 7, 'Cuatro estados', 'suspended, running, dead y normal, la que reanudó a otra y espera');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 8, 'Un error dentro', 'No se propaga: mata la corrutina y sale por el primer valor de resume');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 9, 'coroutine.wrap', 'Invierte esa decisión y vuelve a lanzar el error al llamante');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 10, 'coroutine.close', 'Para lo que quedó suspendido y nadie va a reanudar jamás');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 11, 'La frontera de C', 'El Lua clásico no puede suspender un marco de C por debajo');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 12, 'Generadores', 'Producir bajo demanda sin materializar nunca la secuencia entera');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 13, 'Productor y consumidor', 'Sin cola intermedia el control de flujo sale gratis');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 14, 'Un planificador', 'Cola de listas, bucle que reanuda y temporizadores ordenados por plazo');
INSERT INTO cheatsheet_item VALUES ('lua', 8, 15, 'El await que te fabricas', 'Ceder esperando, y que la llamada de vuelta reanude al llegar');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 0, 'Un módulo es convención', 'Un chunk cuyo valor de retorno alguien guarda en un caché');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 1, 'Sin palabra clave', 'Ni import ni namespace: una función de biblioteca sostiene todo el sistema');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 2, 'Las cuatro fases', 'Mirar el caché, buscar cargador, ejecutarlo y anotar el resultado');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 3, 'package.loaded', 'El caché, y la razón exacta de que un módulo sea un singleton del proceso');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 4, 'package.preload', 'Registrar un cargador a mano, antes de tocar el disco');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 5, 'Los buscadores', 'Una lista ordenada, y de su orden salen todas las precedencias');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 6, 'package.path', 'Plantillas con interrogante donde entra el nombre ya traducido');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 7, 'package.cpath', 'Lo mismo para bibliotecas en C, con su función de apertura');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 8, 'package.config', 'Anuncia el separador de directorios de la plataforma');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 9, 'require nunca recarga', 'Y vaciar el caché a mano deja referencias viejas sueltas por ahí');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 10, 'La tabla local', 'Declararla arriba, rellenarla y devolverla en la última línea');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 11, 'Dependencias en la cabecera', 'Los require arriba se ven de un vistazo y quedan en locales');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 12, 'Estado en el módulo', 'Lo compartes con todo el proceso, lo hayas pensado o no');
INSERT INTO cheatsheet_item VALUES ('lua', 9, 13, 'loadfile con entorno', 'El cuarto argumento carga el chunk con su propio _ENV');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 0, 'Sin excepciones', 'Ni jerarquía ni sintaxis de captura: una función que lanza y otra que protege');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 1, 'error', 'Lanza cualquier valor, no solo una cadena');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 2, 'El nivel', 'Decide qué línea se culpa, y la posición solo se añade a las cadenas');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 3, 'assert', 'No es azúcar sintáctico: sus argumentos se evalúan en cada vuelta');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 4, 'pcall', 'Ejecuta en modo protegido y antepone un booleano al resultado');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 5, 'xpcall', 'Su manejador corre antes de desenrollar: de ahí sale el único rastro útil');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 6, 'El idioma del nil', 'Devolver nil y un mensaje cuando el fallo era previsible');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 7, 'Cuándo lanzar', 'Cuando quien llama no puede hacer nada con el fallo');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 8, 'Las dos convenciones', 'Se convierten la una en la otra con pcall o con assert');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 9, 'Añadir contexto', 'Relanzar envolviendo, sin destruir el mensaje original');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 10, 'Sin bloque final', 'La limpieza va en un <close> o después del pcall');
INSERT INTO cheatsheet_item VALUES ('lua', 10, 11, 'Error dentro del manejador', 'No se maneja de nuevo: se pierde el primero, que era el importante');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 0, 'Nueve bibliotecas', 'Todo el catálogo cabe en una lección, y eso es la tesis del lenguaje');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 1, 'Lo que no trae', 'Ni JSON, ni sockets, ni regex, ni hilos, ni criptografía');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 2, 'Por qué falta', 'Lo que no se puede escribir en C portable se queda fuera');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 3, 'El manejador de fichero', 'Un objeto con metatabla, no un descriptor desnudo');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 4, 'Ficheros por defecto', 'io.read e io.write llevan dos variables globales ocultas detrás');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 5, 'io.lines', 'El único de la biblioteca que se ocupa de cerrar por ti');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 6, 'os.clock frente a os.time', 'Tiempo de proceso para medir, tiempo civil para fechar');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 7, 'os.execute', 'Devuelve cómo terminó, no lo que imprimió: para eso está io.popen');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 8, 'Inyección de órdenes', 'Lua no escapa argumentos: valida contra una lista o no lo uses');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 9, 'math.random', 'Desde 5.4 es xoshiro propio: misma semilla, misma secuencia en cualquier sitio');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 10, 'Sin sesgo de módulo', 'Con rango descarta y vuelve a tirar en lugar de calcular un resto');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 11, 'luac', 'Sirve para comprobar sintaxis y estudiar bytecode; portabilidad no promete');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 12, 'El cisma de 5.1', 'LuaJIT se quedó ahí y el ecosistema quedó partido en dos mundos');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 13, 'Romper entre versiones', 'Política deliberada: el tamaño se paga en compatibilidad');
INSERT INTO cheatsheet_item VALUES ('lua', 11, 14, 'LuaRocks', 'Árboles por versión, y el criterio de copiar el fichero y seguir');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 0, 'load', 'El compilador expuesto como función corriente: de texto a chunk ejecutable');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 1, 'El chunk es vararg', 'Y lleva _ENV en su primer upvalue, siempre');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 2, 'El cuarto argumento', 'Fija ese _ENV: de ahí salen la configuración como código y el sandbox');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 3, 'Texto o binario', 'El modo de load es una decisión de seguridad, no de comodidad');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 4, 'El nombre del chunk', 'Gobierna lo que vas a leer en el mensaje de error');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 5, 'string.dump', 'Vuelca el bytecode de una función; de vuelta, las funciones no viajan');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 6, '%q', 'La base de serializar: escribe el valor como Lua que se puede releer');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 7, 'Ciclos e identidad', 'Dos fases: declarar las tablas y después coserlas entre sí');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 8, 'debug.getinfo', 'Quién llamó y desde qué línea, sin instrumentar nada');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 9, 'debug.sethook', 'Ganchos de llamada, retorno, línea y cuenta: la base de un profiler');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 10, 'Marcado y barrido', 'No cuenta referencias: sigue caminos desde las raíces');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 11, 'Tres colores', 'Blanco sin visitar, gris pendiente, negro terminado');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 12, 'El invariante tricolor', 'Ningún objeto negro apunta a uno blanco, o se pierde algo vivo');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 13, 'Barrera de escritura', 'El precio obligatorio de trocear el ciclo en pasos');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 14, 'collectgarbage', 'Contar, forzar, dar un paso, detener y afinar los parámetros');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 15, 'Generacional', 'Los recién nacidos se revisan a menudo; los veteranos casi nunca');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 16, 'El cambio de 5.5', 'Las recolecciones mayores pasan a ser incrementales: sin pausa catastrófica');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 17, 'Tablas débiles', 'Observan sin retener: cachés que sí dejan liberar');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 18, 'Efímeros', 'Resuelven el ciclo en que la clave solo se alcanza desde su valor');
INSERT INTO cheatsheet_item VALUES ('lua', 12, 19, 'Resurrección', 'Un finalizador puede devolver el objeto al mundo de los vivos');
