INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 0, 'La unidad de invalidación', 'Lo que el motor tira y vuelve a producir');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 1, 'Es un eje, no dos bandos', 'Documento, componente, expresión, atributo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 2, 'Re-render', 'Rehacer la descripción entera y comparar con la anterior');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 3, 'Grano fino', 'Cada expresión es un efecto atado a su nodo del DOM');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 4, 'Lo que cuesta el grueso', 'Trabajo proporcional a la salida, no al cambio');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 5, 'Lo que cuesta el fino', 'Memoria y contabilidad del grafo, se use o no');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 6, 'Moverse a la derecha', 'Menos trabajo por cambio, más libros que llevar');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 7, 'Lo que gana el diff', 'Sin nada a lo que suscribirse no hay fuga posible');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 8, 'No hay ganador', 'Interrumpibilidad, tamaño y bugs también pesan');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 0, 9, 'La granularidad real', 'La fija tu código, no el framework del README');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 0, 'Fuente', 'Valor, observadores y una función de igualdad');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 1, 'Computación', 'Un cuerpo que reejecutar y de quién leyó la última vez');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 2, 'Derivación', 'Fuente y computación a la vez: ocupa el centro');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 3, 'Efecto', 'Hoja: existe por lo que hace fuera del sistema');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 4, 'Aristas en dos sentidos', 'Propagar baja; desatar y verificar suben');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 5, 'Quitar una dirección', 'Ahorras memoria y pierdes el desatado barato');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 6, 'Tres representaciones', 'Conjunto, arrays con índices cruzados, lista enlazada');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 7, 'Índices cruzados', 'Baja en tiempo constante sin recorrer el array');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 8, 'Aciclicidad', 'Un ciclo en el grafo es una cascada que no termina');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 1, 9, 'Profundidad y anchura', 'Predicen el coste de cada propagación concreta');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 0, 'El observador actual', 'Una variable de módulo: guardar, asignar, restaurar');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 1, 'Leer teje la arista', 'El grafo se construye ejecutando, no analizando');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 2, 'Desatar antes de correr', 'Sin eso quedan aristas de ramas que ya no se leen');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 3, 'Dependencias condicionales', 'El grafo cambia cada pasada, y por eso es exacto');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 4, 'El cortocircuito corta', 'Lo que no llega a evaluarse no queda suscrito');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 5, 'El orden de lectura importa', 'Dos ramas iguales pueden dejar aristas distintas');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 6, 'Leer sin rastrear', 'Consultar el valor sin quedar suscrito a él');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 7, 'Límite: asincronía', 'Después de esperar ya no hay observador que anotar');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 8, 'Límite: fuera de ámbito', 'Lo leído antes de entrar no lo ve el efecto');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 9, 'Límite: escritura lateral', 'Si no pasa por la fuente, nadie se entera');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 2, 10, 'Límite: colecciones', 'Un Map nativo no avisa de sus propias mutaciones');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 0, 'Push puro', 'Al escribir, recalcular en cascada toda la descendencia');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 1, 'Lo que rompe push', 'Trabajo inútil y valores imposibles en el rombo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 2, 'Pull puro', 'Nadie recalcula nada hasta que alguien lee');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 3, 'Lo que rompe pull', 'Sin glitches, pero hay que preguntar arriba siempre');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 4, 'El híbrido', 'Escribir empuja una marca; leer tira del cálculo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 5, 'Limpio', 'La caché vale y la lectura no comprueba nada');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 6, 'Sucio', 'Certeza local: una fuente mía cambió de valor');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 7, 'Quizá sucio', 'Sospecha heredada: hay que preguntar antes de decidir');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 3, 8, 'Por qué no bastan dos', 'Sin el intermedio nadie puede cortar la cadena');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 0, 'El rombo', 'Dos caminos hasta el mismo nodo, y llegan desfasados');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 1, 'Glitch', 'Evaluar mezclando entradas de dos estados globales');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 2, 'Glitch-free', 'Nadie llega a observar un estado que nunca existió');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 3, 'Obsoleto no es inconsistente', 'Ver el mundo de antes es válido; mezclarlo no');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 4, 'El daño que persiste', 'Un valor imposible persistido sobrevive a la sesión');
