INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 6, 'Resolver hacia arriba', 'Impone el orden topológico sin llegar a calcularlo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 7, 'Orden topológico explícito', 'Altura por nodo y cola de prioridad: la vía clásica');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 4, 8, 'Versiones y épocas', 'Comparar contadores en vez de ordenar el grafo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 0, 'Qué es un memo', 'Nodo perezoso que es fuente y computación a la vez');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 1, 'No es una caché con clave', 'Lo invalida el grafo, no unos argumentos');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 2, 'Cortacircuitos', 'Si no cambia de valor, los de abajo no se ensucian');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 3, 'La igualdad es la frontera', 'Decide qué cuenta como cambio, y dónde para todo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 4, 'Identidad', 'Barata; un objeto nuevo idéntico propaga igual');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 5, 'Comparación estructural', 'Corta más propagación y la paga en cada escritura');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 6, 'Desactivarla', 'Propagar siempre: útil cuando mutas en el sitio');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 7, 'El memo que nadie lee', 'Sin observadores no se evalúa aunque cambie su fuente');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 5, 8, 'Cuándo no compensa', 'Nodo, aristas y comparación por un cálculo trivial');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 6, 0, 'El dueño actual', 'La segunda variable global: quién posee lo que se cree');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 6, 1, 'Es un árbol', 'Cada cosa nace dentro de exactamente una ejecución');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 6, 2, 'Hijos y limpiezas', 'Lo que se creó y lo que habrá que deshacer');
