INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 6, 4, 'Entre reejecuciones', 'Cada pasada limpia lo que creó la anterior');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 6, 5, 'Raíz desacoplada', 'Un ámbito de nadie, que se desecha a mano');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 6, 6, 'Capturar y volver', 'La salida de emergencia para el código diferido');
