INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 7, 2, 'Puras antes que efectos', 'Derivar todo primero; solo después tocar el mundo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 7, 3, 'Efecto que escribe', 'Ensucia a otros dentro del mismo vaciado');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 7, 4, 'Tope de cascadas', 'Sin él, dos efectos que se responden cuelgan la pestaña');
