INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 7, 7, 'Elegir el momento', 'Antes de actualizar el DOM, después, o ya mismo');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 8, 0, 'Atómico o profundo', 'No es sintaxis: cambia granularidad y atomicidad');
