INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 8, 8, 'Las salidas', 'No desestructurar, envolver por propiedad, o compilar');
INSERT INTO cheatsheet_item VALUES ('reactividad-fina', 9, 0, 'Lo que comparten los cinco', 'Tracking automático, push-pull y glitch-free');
