INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 2, 'Cache first', 'La única correcta para ficheros con hash en el nombre');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 3, 'Network first', 'Sin tiempo límite, una red mala es peor que no tener red');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 4, 'Stale while revalidate', 'La opción por defecto para lo que no es crítico ni tiene hash');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 5, 'response.clone()', 'El cuerpo se consume una vez: clona antes de leer nada');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 6, 'Respuestas opacas', 'Reservan cuota inflada aunque el recurso pese poco');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 7, 'Vía de escape', 'Un worker mal desplegado se queda: ten el interruptor listo');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 8, 'Clave de caché', 'Método, esquema, host, ruta, query y lo que añada Vary');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 9, 'Cardinalidad', 'Cada dimensión que añades divide la tasa de aciertos');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 10, 'Coste de un tercero', 'Cinco partidas, y los bytes suelen ser la más pequeña');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 11, 'Patrón de fachada', 'Pinta el marcador y carga el widget solo si lo tocan');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 14, 12, 'Partytown', 'Gana con cómputo propio y pierde en cada acceso al DOM');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 0, 'Lighthouse CI', 'Cinco pasadas y no tres: con tres la mediana sigue bailando');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 1, 'Limitación simulada', 'En CI quieres comparabilidad, no fidelidad al dispositivo');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 2, 'Ejecutor compartido', 'Un instrumento de medida con la CPU de otro trabajo encima');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 3, 'Presupuestos', 'Falla el build solo sobre métricas deterministas');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 4, 'El mensaje de error', 'Que traiga el diagnóstico, no el síntoma con un número');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 5, 'Vía de excepción', 'Documentada y con caducidad, o alguien quita la puerta');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 6, 'Diff del bundle', 'Cuántos KB creció y qué dependencia los trajo');
INSERT INTO cheatsheet_item VALUES ('rendimiento', 15, 7, 'Cada commit y cada noche', 'Lo determinista en el PR; el dispositivo real de madrugada');
